SELECT 
FROM TBL_TREASURY_EXCHANGE_RATES


        AND BASE_CURRENCY = #{baseCurrency}


        AND TARGET_CURRENCY = #{targetCurrency}


        AND RATE_TYPE = #{rateType}


        AND RATE_DATE = #{rateDate}


        AND DATA_SOURCE = #{dataSource}


        AND IS_ENABLED = #{isEnabled}


        AND ORG_ID = #{orgId}


ORDER BY RATE_DATE DESC, CREATE_TIME DESC

SELECT 
FROM TBL_TREASURY_EXCHANGE_RATES
WHERE BASE_CURRENCY = #{baseCurrency}
  AND TARGET_CURRENCY = #{targetCurrency}
  AND RATE_DATE = #{rateDate}
  AND RATE_TYPE = #{rateType}
  AND ORG_ID = #{orgId}
ORDER BY CREATE_TIME DESC
LIMIT 1

SELECT 
FROM TBL_TREASURY_EXCHANGE_RATES
WHERE BASE_CURRENCY = #{baseCurrency}
  AND TARGET_CURRENCY = #{targetCurrency}
  AND RATE_TYPE = #{rateType}
  AND ORG_ID = #{orgId}
ORDER BY RATE_DATE DESC, CREATE_TIME DESC
LIMIT 1

SELECT 
FROM TBL_TREASURY_EXCHANGE_RATES
WHERE BASE_CURRENCY = #{baseCurrency}
  AND TARGET_CURRENCY = #{targetCurrency}
  AND RATE_DATE BETWEEN #{startDate} AND #{endDate}
  AND ORG_ID = #{orgId}
ORDER BY RATE_DATE DESC

SELECT COUNT(1)
FROM TBL_TREASURY_EXCHANGE_RATES
WHERE BASE_CURRENCY = #{baseCurrency}
  AND TARGET_CURRENCY = #{targetCurrency}
  AND RATE_DATE = #{rateDate}
  AND RATE_TYPE = #{rateType}
  AND ORG_ID = #{orgId}

    AND RATE_ID != #{excludeId}
